import * as THREE from './vendor/three.module.js';

(() => {
  'use strict';
  const $ = (id) => document.getElementById(id);
  const ui = Object.fromEntries(['menuScreen','hud','playerPanel','objective','mobileControls','pauseButton','desktopHelp','reticle','toast','scorePlayer','scoreEnemy','clock','healthValue','healthBar','ammoClip','ammoReserve','weaponName','weaponSkin','hitMarker','damageFlash','killFeed','interaction','roundScreen','roundTitle','roundCopy','resultPlayer','resultEnemy','pauseScreen','caseModal','caseReward','credits','weaponSelect','skinSelect','continueButton','startButton','openCase','closeCase','rollCase','resumeButton','pauseButton','menuButton','returnMenu','fireTouch','reloadTouch','knifeTouch','movePad','moveKnob'].map(id => [id, $(id)]));
  const canvas = $('game');
  const isTouch = matchMedia('(pointer: coarse)').matches;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a,b) => a + Math.random() * (b-a);
  const V3 = (x=0,y=0,z=0) => new THREE.Vector3(x,y,z);
  const weaponData = {
    rifle:{name:'R-4 VANDAL',clip:30,reserve:120,damage:34,rate:.105,reload:1.55,spread:.012,color:0x53624b},
    pistol:{name:'PX-9 SIDEARM',clip:15,reserve:75,damage:44,rate:.23,reload:1.2,spread:.009,color:0x454d4b},
    shotgun:{name:'BULL-12 SHOTGUN',clip:8,reserve:40,damage:18,rate:.72,reload:1.8,spread:.085,color:0x674e39},
    knife:{name:'FIELD KNIFE',clip:'∞',reserve:'',damage:70,rate:.42,reload:0,spread:0,color:0x87908a}
  };
  const skinData = {standard:{label:'FIELD STANDARD',color:0x53624b},ember:{label:'EMBER STRIKE',color:0xc55332},arctic:{label:'ARCTIC CIRCUIT',color:0x5ca8bb},toxic:{label:'TOXIC BLOOM',color:0x87bd45},royal:{label:'ROYAL FLUSH',color:0x8459b7}};
  let scene,camera,renderer,clock3,worldGroup,weaponRig,weaponMesh,muzzleLight;
  let state='menu', player, bots=[], props=[], tracers=[], particles=[], credits=1250, scorePlayer=0,scoreEnemy=0,round=1,roundTime=120, toastTimer=0, hitTimer=0, damageTimer=0, fireTimer=0,reloadTimer=0,knifeTimer=0,caseBusy=false,elapsed=0;
  let yaw=0,pitch=0,locked=false,fireHeld=false, moveInput={x:0,y:0}, padPointer=null,padCenter=null, lastTouchX=null,lastTouchY=null;
  const keys=new Set();
  const map={w:22,h:16};
  const obstacleDefs=[
    {x:-7,z:-4,w:5,d:1.3,type:'container',label:'CARGO 04'}, {x:-5.5,z:-2.7,w:1.2,d:2.4,type:'container'},
    {x:5,z:3.6,w:5.2,d:1.25,type:'container',label:'CARGO 12'}, {x:7,z:5,w:1.2,d:2.5,type:'container'},
    {x:-10,z:2,w:2.2,d:1.3,type:'crate'}, {x:-8.5,z:2.9,w:1,d:1.5,type:'crate'},
    {x:9,z:-3.2,w:2.1,d:1.25,type:'crate'}, {x:7.9,z:-2.1,w:1,d:1.65,type:'crate'},
    {x:-3,z:6.3,w:3.1,d:1.25,type:'wall'}, {x:-1.3,z:7.3,w:1.15,d:2.2,type:'wall'},
    {x:9.2,z:6.5,w:3.2,d:1.2,type:'wall'}, {x:10,z:5.5,w:1.25,d:1.6,type:'wall'},
    {x:-1.1,z:-6.8,w:1.4,d:1.4,type:'crate'}, {x:1.2,z:-1.7,w:1.5,d:1.2,type:'crate'},
    {x:-4.8,z:1.1,w:1.3,d:1.2,type:'crate'}, {x:4.5,z:-1.3,w:1.5,d:1.2,type:'crate'},
    {x:3.5,z:7.8,w:2.2,d:1.2,type:'crate'}, {x:-11,z:-5,w:1.4,d:1.2,type:'crate'},
  ];
  const obstacleMeshes=[];
  const tempColor = new THREE.Color();

  function init(){
    renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
    renderer.setPixelRatio(Math.min(devicePixelRatio||1,2));renderer.setSize(innerWidth,innerHeight,false);
    renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
    scene=new THREE.Scene();scene.background=new THREE.Color(0x86928c);scene.fog=new THREE.Fog(0x86928c,24,58);
    camera=new THREE.PerspectiveCamera(76,innerWidth/innerHeight,.08,100);camera.rotation.order='YXZ';
    scene.add(new THREE.HemisphereLight(0xdce9da,0x394239,2.1));
    const sun=new THREE.DirectionalLight(0xffe6c6,2.4);sun.position.set(-12,22,10);scene.add(sun);
    worldGroup=new THREE.Group();scene.add(worldGroup);clock3=new THREE.Clock();
    buildArena();buildWeapon();resize();window.addEventListener('resize',resize);bindUI();
    camera.position.set(0,1.7,12);yaw=0;pitch=0;
    renderer.setAnimationLoop(frame);
  }
  function mat(color,roughness=.85,metalness=0){return new THREE.MeshStandardMaterial({color,roughness,metalness});}
  function box(parent,x,y,z,w,h,d,material){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.castShadow=false;m.receiveShadow=true;parent.add(m);return m;}
  function buildArena(){
    const floor=box(worldGroup,0,-.18,0,45,.35,34,mat(0x616b5e));
    box(worldGroup,0,-.01,0,43,.08,32,mat(0x777e6c));
    // worn concrete panels and service-lane paint
    const seam=mat(0x515b51), pale=mat(0xa6a486), paint=mat(0x9b8a63);
    for(let x=-20;x<=20;x+=2)box(worldGroup,x,.035,0,.018,.012,31,seam);
    for(let z=-14;z<=14;z+=2)box(worldGroup,0,.036,z,42,.012,.018,seam);
    box(worldGroup,0,.04,0,42,.012,1.5,paint);box(worldGroup,0,.045,-.82,42,.014,.025,seam);box(worldGroup,0,.045,.82,42,.014,.025,seam);
    box(worldGroup,0,.04,0,.025,.014,30,pale);
    // perimeter walls and raised barriers
    const wall=mat(0x46534a), dark=mat(0x2d3934);
    box(worldGroup,0,1.5,-16.3,44,3, .5,wall);box(worldGroup,0,1.5,16.3,44,3,.5,wall);box(worldGroup,-21.8,1.5,0,.5,3,32,dark);box(worldGroup,21.8,1.5,0,.5,3,32,dark);
    for(let x=-20;x<21;x+=2){box(worldGroup,x,.08,-15.95,1,.08,.08,paint);box(worldGroup,x,.08,15.95,1,.08,.08,paint);}
    // background silhouettes / yard structures
    const shed=mat(0x3f4a43), roof=mat(0x343e38);
    box(worldGroup,-15,2,-9,7,4,5,shed);box(worldGroup,-15,4.1,-9,7.3,.25,5.3,roof);
    box(worldGroup,15,2,10,7,4,5,shed);box(worldGroup,15,4.1,10,7.3,.25,5.3,roof);
    // obstacle geometry and matching collision footprints
    for(const o of obstacleDefs){const h=o.type==='container'?2.45:o.type==='wall'?1.45:1.25;const color=o.type==='container'?(o.label==='CARGO 04'?0x344c49:0x485343):o.type==='wall'?0x4c554b:0x816c4e;
      const g=new THREE.Group();g.position.set(o.x,0,o.z);worldGroup.add(g);
      box(g,0,h/2,0,o.w,h,o.d,mat(color));
      if(o.type==='container'){
        const rib=mat(0x273c39);for(let xx=-o.w/2+.18;xx<o.w/2;xx+=.34)box(g,xx,h/2,0,.035,h-.1,o.d+.025,rib);
        box(g,0,h-.19,o.d/2+.02,o.w-.12,.06,.04,mat(0xa3946c));
        box(g,0,.18,o.d/2+.025,o.w-.12,.08,.04,mat(0x263936));
      } else {
        box(g,0,h+.025,0,o.w+.03,.07,o.d+.03,mat(o.type==='crate'?0x9a8059:0x687164));
        if(o.type==='crate'){const strap=mat(0x514b3c);box(g,0,h/2,0,.09,h+.04,o.d+.04,strap);box(g,0,h/2,0,o.w+.04,h+.04,.08,strap);}
      }
      obstacleMeshes.push({x:o.x,z:o.z,w:o.w,d:o.d});
    }
    // lights and a central marked objective ring
    const ring=new THREE.Mesh(new THREE.TorusGeometry(2.2,.045,5,64),mat(0xd3a95f));ring.rotation.x=Math.PI/2;ring.position.set(0,.08,0);worldGroup.add(ring);
    for(let i=0;i<8;i++){const a=i*Math.PI/4;const bollard=new THREE.Mesh(new THREE.CylinderGeometry(.13,.16,.8,8),mat(0x687365));bollard.position.set(Math.cos(a)*3.1,.4,Math.sin(a)*3.1);worldGroup.add(bollard);}
    addCrate(-12,-1);addCrate(11,-8);addCrate(2,9);
    // scattered ground markings and light poles
    for(let i=0;i<38;i++){const x=rand(-19,19),z=rand(-14,14);const patch=new THREE.Mesh(new THREE.CircleGeometry(rand(.08,.38),7),mat(i%2?0x656d5f:0x85806b));patch.rotation.x=-Math.PI/2;patch.position.set(x,.045,z);worldGroup.add(patch);}
    for(const [x,z] of [[-18,-12],[18,-12],[-18,12],[18,12]]){const pole=mat(0x37423b);box(worldGroup,x,3.8,z,.12,7.6,.12,pole);const lamp=new THREE.PointLight(0xffd69a,4,10);lamp.position.set(x,7.2,z);scene.add(lamp);}
  }
  function addCrate(x,z){
    const g=new THREE.Group();g.position.set(x,0,z);worldGroup.add(g);
    box(g,0,.55,0,.95,1.1,.9,mat(0x766044));box(g,0,1.13,0,1.02,.08,.96,mat(0x9b814f));
    const band=mat(0xc8ed76);box(g,0,.58,.47,.12,1.08,.04,band);box(g,0,.58,-.47,.12,1.08,.04,band);
