  function buildWeapon(){
    weaponRig=new THREE.Group();camera.add(weaponRig);weaponRig.position.set(.32,-.28,-.55);
    const bodyMat=mat(0x53624b,.35,.5);weaponMesh=new THREE.Group();weaponRig.add(weaponMesh);
    box(weaponMesh,0,0,0,.16,.14,.48,bodyMat);box(weaponMesh,0,.045,-.32,.075,.075,.55,mat(0x252c29,.32,.7));
    box(weaponMesh,0,-.13,.08,.12,.19,.14,mat(0x292f2b));box(weaponMesh,0,.105,-.05,.05,.04,.22,mat(0x181d1b));
