function bindUI(){
  $('startButton').addEventListener('click',()=>deploy());$('continueButton').addEventListener('click',()=>{ui.roundScreen.classList.add('hidden');if(scorePlayer>=3||scoreEnemy>=3){toMenu();return;}round++;deployRound();});
  $('pauseButton').addEventListener('click',pause);$('resumeButton').addEventListener('click',resume);$('menuButton').addEventListener('click',toMenu);$('returnMenu').addEventListener('click',toMenu);
  $('weaponSelect').addEventListener('change',()=>{if(player){player.weapon=$('weaponSelect').value;const d=weaponData[player.weapon];player.ammo=d.clip;player.reserve=d.reserve;rebuildWeapon();updateHUD();}});
  $('skinSelect').addEventListener('change',rebuildWeapon);
  $('openCase').addEventListener('click',()=>{ui.caseModal.classList.remove('hidden');ui.caseReward.textContent='A mystery finish awaits.';});$('closeCase').addEventListener('click',()=>{if(!caseBusy)ui.caseModal.classList.add('hidden');});
  $('rollCase').addEventListener('click',openCase);
  canvas.addEventListener('click',()=>{if(state==='playing'&&!isTouch&&!locked)canvas.requestPointerLock?.();});
  document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===canvas;});
  document.addEventListener('mousemove',e=>{if(state==='playing'&&locked){yaw-=e.movementX*.0022;pitch=clamp(pitch-e.movementY*.0018,-1.25,1.25);}});
  canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&state==='playing'){fireHeld=true;if(!locked)canvas.requestPointerLock?.();}});
  window.addEventListener('pointerup',e=>{if(e.pointerType==='mouse')fireHeld=false;});
  canvas.addEventListener('touchstart',e=>{if(state==='playing'&&e.touches.length){lastTouchX=e.touches[0].clientX;lastTouchY=e.touches[0].clientY;}},{passive:true});
  canvas.addEventListener('touchmove',e=>{if(state!=='playing'||!e.touches.length)return;const t=e.touches[0];if(lastTouchX!==null){yaw-=(t.clientX-lastTouchX)*.006;pitch=clamp(pitch-(t.clientY-lastTouchY)*.004,-1.2,1.2);}lastTouchX=t.clientX;lastTouchY=t.clientY;},{passive:true});
  canvas.addEventListener('touchend',()=>{lastTouchX=null;lastTouchY=null;});
  window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();keys.add(key);if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(key))e.preventDefault();if(key==='escape'){if(state==='playing')pause();else if(state==='paused')resume();}if(key==='r')reload();if(key==='e')interact();if(key==='1')switchWeapon('rifle');if(key==='2')switchWeapon('pistol');if(key==='3')switchWeapon('knife');if(key==='4')switchWeapon('shotgun');});
  window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
  $('fireTouch').addEventListener('pointerdown',e=>{e.preventDefault();fireHeld=true;$('fireTouch').setPointerCapture(e.pointerId);});$('fireTouch').addEventListener('pointerup',()=>fireHeld=false);$('fireTouch').addEventListener('pointercancel',()=>fireHeld=false);
  $('reloadTouch').addEventListener('pointerdown',e=>{e.preventDefault();reload();});$('knifeTouch').addEventListener('pointerdown',e=>{e.preventDefault();switchWeapon('knife');});
  ui.movePad.addEventListener('pointerdown',e=>{e.preventDefault();padPointer=e.pointerId;const r=ui.movePad.getBoundingClientRect();padCenter={x:r.left+r.width/2,y:r.top+r.height/2};ui.movePad.setPointerCapture(e.pointerId);updatePad(e);});
  ui.movePad.addEventListener('pointermove',e=>{if(e.pointerId===padPointer)updatePad(e);});
  ['pointerup','pointercancel'].forEach(ev=>ui.movePad.addEventListener(ev,e=>{if(e.pointerId!==padPointer)return;padPointer=null;padCenter=null;moveInput={x:0,y:0};ui.moveKnob.style.left='50%';ui.moveKnob.style.top='50%';}));
  window.addEventListener('blur',()=>{fireHeld=false;keys.clear();});
}
function updatePad(e){if(!padCenter)return;const dx=e.clientX-padCenter.x,dy=e.clientY-padCenter.y,len=Math.hypot(dx,dy),max=38,m=Math.min(1,len/max);moveInput={x:len?dx/len*m:0,y:len?dy/len*m:0};ui.moveKnob.style.left=`calc(50% + ${moveInput.x*max}px)`;ui.moveKnob.style.top=`calc(50% + ${moveInput.y*max}px)`;}
function deploy(){scorePlayer=0;scoreEnemy=0;round=1;state='playing';ui.menuScreen.classList.add('hidden');ui.roundScreen.classList.add('hidden');ui.pauseScreen.classList.add('hidden');ui.hud.classList.remove('hidden');ui.playerPanel.classList.remove('hidden');ui.objective.classList.remove('hidden');ui.pauseButton.classList.remove('hidden');ui.mobileControls.classList.toggle('hidden',!isTouch);ui.desktopHelp.classList.toggle('hidden',isTouch);ui.reticle.classList.toggle('hidden',isTouch);ui.killFeed.innerHTML='';deployRound();if(!isTouch)canvas.requestPointerLock?.();}
function deployRound(){
  state='playing';roundTime=120;fireTimer=reloadTimer=knifeTimer=0;fireHeld=false;moveInput={x:0,y:0};yaw=0;pitch=0;
  bots.forEach(b=>scene.remove(b.group));bots=[];tracers.forEach(t=>scene.remove(t.line));tracers=[];
  const weapon=$('weaponSelect').value, data=weaponData[weapon];player={x:0,z:12,hp:100,weapon,ammo:data.clip,reserve:data.reserve,alive:true,kills:0};
