function makeBot(x,z,name){
  const group=new THREE.Group(), uniform=mat(0x5b463d), vest=mat(0x3b4740), helmet=mat(0x38443d), skin=mat(0xb1886c), gun=mat(0x252b28,.35,.55);
  const body=new THREE.Mesh(new THREE.CapsuleGeometry(.31,.67,4,8),uniform);body.position.y=.95;group.add(body);
  const armor=box(group,0,1.05,0,.54,.48,.35,vest);const head=new THREE.Mesh(new THREE.SphereGeometry(.22,12,10),skin);head.position.set(0,1.56,0);group.add(head);
  const hat=new THREE.Mesh(new THREE.SphereGeometry(.24,12,8,0,Math.PI*2,0,Math.PI/2),helmet);hat.position.set(0,1.65,0);group.add(hat);
