  const indicator=new THREE.Mesh(new THREE.CircleGeometry(.38,16),mat(0xe3795f));indicator.rotation.x=-Math.PI/2;indicator.position.y=.03;group.add(indicator);
  const hpGroup=new THREE.Group();hpGroup.position.set(0,2.1,0);group.add(hpGroup);box(hpGroup,0,0,0,.8,.07,.035,mat(0x181d19));const bar=box(hpGroup,0,0,0,.76,.045,.04,mat(0xed8063));
  group.position.set(x,0,z);scene.add(group);return{x,z,hp:100,alive:true,name,group,bar,cool:rand(.8,2),think:rand(0,2),strafe:Math.random()<.5?-1:1,body,damageFlash:0};
}
function switchWeapon(weapon){if(!player||state!=='playing')return;if(weapon==='shotgun'&&$('weaponSelect').value!=='shotgun'){showToast('SHOTGUN NOT IN CURRENT LOADOUT');return;}player.weapon=weapon;if(weapon!=='knife'){const d=weaponData[weapon];player.ammo=d.clip;player.reserve=d.reserve;}reloadTimer=0;rebuildWeapon();updateHUD();}
function pause(){if(state!=='playing')return;state='paused';ui.pauseScreen.classList.remove('hidden');document.exitPointerLock?.();}
function resume(){if(state!=='paused')return;state='playing';ui.pauseScreen.classList.add('hidden');if(!isTouch)canvas.requestPointerLock?.();}
function toMenu(){state='menu';ui.menuScreen.classList.remove('hidden');ui.pauseScreen.classList.add('hidden');ui.roundScreen.classList.add('hidden');ui.hud.classList.add('hidden');ui.playerPanel.classList.add('hidden');ui.objective.classList.add('hidden');ui.mobileControls.classList.add('hidden');ui.pauseButton.classList.add('hidden');ui.desktopHelp.classList.add('hidden');ui.reticle.classList.add('hidden');ui.interaction.classList.add('hidden');document.exitPointerLock?.();fireHeld=false;}
function updateHUD(){
  ui.scorePlayer.textContent=scorePlayer;ui.scoreEnemy.textContent=scoreEnemy;ui.clock.textContent=`${String(Math.floor(Math.max(0,roundTime)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,roundTime)%60)).padStart(2,'0')}`;
  if(player){const d=weaponData[player.weapon];ui.healthValue.textContent=Math.max(0,Math.ceil(player.hp));ui.healthBar.style.width=`${clamp(player.hp,0,100)}%`;ui.healthBar.style.background=player.hp<35?'#ed836b':'#c8ed76';ui.ammoClip.textContent=player.weapon==='knife'?'∞':player.ammo;ui.ammoReserve.textContent=player.weapon==='knife'?'':player.reserve;ui.weaponName.textContent=d.name;ui.weaponSkin.textContent=player.weapon==='knife'?'FIELD ISSUE':skinData[$('skinSelect').value].label;}
  ui.credits.textContent=credits.toLocaleString();
}
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=1.65;}
function feed(killer,victim,enemy=false){const item=document.createElement('div');item.className=`feed-item${enemy?' enemy':''}`;item.textContent=`${killer}  ›  ${victim}`;ui.killFeed.prepend(item);while(ui.killFeed.children.length>4)ui.killFeed.lastChild.remove();setTimeout(()=>item.remove(),4000);}
function reload(){if(state!=='playing'||!player||player.weapon==='knife'||reloadTimer>0||player.ammo>=weaponData[player.weapon].clip||player.reserve<=0)return;reloadTimer=weaponData[player.weapon].reload;showToast('RELOADING');}
function completeReload(){if(reloadTimer<=0)return;reloadTimer-=clock3.getDelta?0:0;}
function openCase(){if(caseBusy)return;if(credits<250){showToast('NOT ENOUGH CREDITS');return;}credits-=250;caseBusy=true;const display=document.querySelector('.case-display');display.classList.add('rolling');ui.caseReward.textContent='ACCESSING SEALED CONTENT…';$('rollCase').disabled=true;
  const skins=['ember','arctic','toxic','royal'];let spins=0;const timer=setInterval(()=>{const s=skins[Math.floor(Math.random()*skins.length)];ui.caseReward.textContent=skinData[s].label;spins++;if(spins>14){clearInterval(timer);display.classList.remove('rolling');caseBusy=false;$('rollCase').disabled=false;$('skinSelect').value=s;rebuildWeapon();updateHUD();ui.caseReward.textContent=`UNLOCKED: ${skinData[s].label}`;showToast(`${skinData[s].label} UNLOCKED`);}},100);updateHUD();}
function interact(){if(state!=='playing'||!player)return;let best=null,bd=2.3;for(const p of props){if(p.opened)continue;const d=Math.hypot(player.x-p.x,player.z-p.z);if(d<bd){bd=d;best=p;}}if(!best){showToast('NO SUPPLY CRATE IN REACH');return;}best.opened=true;best.mesh.visible=false;const roll=Math.random();if(roll<.4){player.hp=Math.min(100,player.hp+30);showToast('FIELD MEDKIT +30 HEALTH');}else if(roll<.8&&player.weapon!=='knife'){player.reserve+=weaponData[player.weapon].clip*2;showToast('AMMO CACHE +2 MAGAZINES');}else{credits+=150;showToast('SALVAGED CRATE +150 CR');}updateHUD();}

