  function playerMove(dt){
    let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0)-moveInput.y;
    let strafe=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+moveInput.x;
    const mag=Math.hypot(forward,strafe);if(mag>1){forward/=mag;strafe/=mag;}
    const speed=keys.has('shift')?6.3:4.7;
    const dx=(-Math.sin(yaw)*forward+Math.cos(yaw)*strafe)*speed*dt,dz=(-Math.cos(yaw)*forward-Math.sin(yaw)*strafe)*speed*dt;
    movePlayerTo(player.x+dx,player.z+dz);
    camera.position.set(player.x,1.66+Math.sin(elapsed*10)*Math.min(.035,mag*.008),player.z);camera.rotation.set(pitch,yaw,0,'YXZ');
  }
  function collides(x,z,r=.36){
    if(x<-20.9||x>20.9||z<-15.1||z>15.1)return true;
    for(const o of obstacleMeshes)if(x>o.x-o.w/2-r&&x<o.x+o.w/2+r&&z>o.z-o.d/2-r&&z<o.z+o.d/2+r)return true;
    return false;
  }
  function movePlayerTo(x,z){if(!collides(x,player.z))player.x=x;if(!collides(player.x,z))player.z=z;}
  function moveBot(b,dx,dz,dt){let x=b.x+dx*dt,z=b.z+dz*dt;if(!collides(x,z,.4)){b.x=x;b.z=z;}else{const sx=b.x-dz*dt,sz=b.z+dx*dt;if(!collides(sx,sz,.4)){b.x=sx;b.z=sz;}}b.group.position.set(b.x,0,b.z);}
  function rayHit(distance=42){
    camera.updateMatrixWorld();const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);ray.far=distance;
    const targets=[...bots.filter(b=>b.alive).map(b=>b.group),...obstacleMeshes.map((o,i)=>worldGroup.children.find(m=>m.position?.x===o.x&&m.position?.z===o.z))].filter(Boolean);
    // obstacle collision is independently ray-tested against footprints for deterministic cover
    let hit=ray.intersectObjects(bots.filter(b=>b.alive).map(b=>b.group),true)[0];
    const dir=ray.ray.direction,origin=ray.ray.origin;let wallDistance=distance;
    for(const o of obstacleMeshes){const t=rayBox(origin,dir,o);if(t!==null&&t<wallDistance)wallDistance=t;}
    if(hit&&hit.distance<=wallDistance)return{bot:bots.find(b=>b.alive&&b.group===rootGroup(hit.object)),point:hit.point,distance:hit.distance};
    return{bot:null,point:origin.clone().addScaledVector(dir,Math.min(wallDistance,distance)),distance:wallDistance};
  }
  function rootGroup(obj){let n=obj;while(n.parent&&n.parent!==scene)n=n.parent;return n;}
  function rayBox(o,d,b){let near=-Infinity,far=Infinity;for(const [v,dir,min,max] of [[o.x,d.x,b.x-b.w/2,b.x+b.w/2],[o.z,d.z,b.z-b.d/2,b.z+b.d/2]]){if(Math.abs(dir)<1e-6){if(v<min||v>max)return null;}else{let a=(min-v)/dir,c=(max-v)/dir;if(a>c)[a,c]=[c,a];near=Math.max(near,a);far=Math.min(far,c);if(near>far)return null;}}return far<0?null:Math.max(0,near);}
  function shoot(){if(state!=='playing'||fireTimer>0||reloadTimer>0||!player)return;const data=weaponData[player.weapon];
    if(player.weapon==='knife'){knifeAttack();fireTimer=data.rate;return;}
    if(player.ammo<=0){reload();if(!player.reserve)showToast('NO AMMO');fireTimer=.22;return;}
    player.ammo--;fireTimer=data.rate;updateHUD();
    const count=player.weapon==='shotgun'?7:1;
    for(let i=0;i<count;i++){const hit=rayHit();if(hit.bot){const damage=player.weapon==='shotgun'?data.damage:Math.round(data.damage*rand(.88,1.13));hurtBot(hit.bot,damage);}
      addTracer(camera.position.clone().add(camera.getWorldDirection(V3()).multiplyScalar(.45)),hit.point,0xf5c277,.11);}
    muzzleLight.intensity=5;setTimeout(()=>{if(muzzleLight)muzzleLight.intensity=0;},55);
    weaponRig.position.z=-.49;setTimeout(()=>{if(weaponRig)weaponRig.position.z=-.58;},65);
  }
  function knifeAttack(){
    const hit=rayHit(2.4);if(hit.bot){const d=hit.distance<1.3?100:70;hurtBot(hit.bot,d);showHit();}weaponRig.rotation.x=-.5;setTimeout(()=>{if(weaponRig)weaponRig.rotation.x=0;},150);
  }
  function hurtBot(bot,damage){if(!bot?.alive)return;bot.hp-=damage;bot.damageFlash=.12;bot.bar.scale.x=Math.max(.001,bot.hp/100);bot.bar.position.x=-(1-bot.hp/100)*.38;showHit();
    if(bot.hp<=0){bot.alive=false;bot.group.rotation.x=Math.PI/2;bot.group.position.y=-.25;scorePlayer++;player.kills++;credits+=100;feed('YOU',bot.name);updateHUD();if(bots.every(b=>!b.alive))endRound(true);}}
  function showHit(){ui.hitMarker.classList.remove('hidden');hitTimer=.12;}
  function addTracer(a,b,color=0xf5c277,life=.11){const geo=new THREE.BufferGeometry().setFromPoints([a,b]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.85}));scene.add(line);tracers.push({line,life});}
  function botUpdate(b,dt){if(!b.alive)return;b.cool-=dt;b.think-=dt;const dx=player.x-b.x,dz=player.z-b.z,dist=Math.hypot(dx,dz);if(dist<.15)return;
    const targetYaw=Math.atan2(-dx,-dz);b.group.rotation.y=targetYaw;
    let mx=0,mz=0;if(dist>8){mx=dx/dist;mz=dz/dist;}else if(dist<4){mx=-dx/dist*.6+Math.cos(elapsed*2+b.x)*.5;mz=-dz/dist*.6+Math.sin(elapsed*2+b.z)*.5;}else{mx=-dz/dist*b.strafe*.35;mz=dx/dist*b.strafe*.35;}
    if(b.think<=0){b.think=rand(1.2,2.4);b.strafe*=-1;}
    moveBot(b,mx*rand(1.35,1.75),mz*rand(1.35,1.75),dt);
    if(dist<20&&b.cool<=0&&clearShot(b,player)){b.cool=rand(.72,1.25);botShoot(b);}
    if(b.damageFlash>0){b.damageFlash-=dt;b.body.material.color.setHex(0xf1a58d);}else b.body.material.color.setHex(0x5b463d);
  }
  function clearShot(b,target){const steps=Math.ceil(Math.hypot(target.x-b.x,target.z-b.z)/.2);for(let i=1;i<steps;i++){const x=b.x+(target.x-b.x)*i/steps,z=b.z+(target.z-b.z)*i/steps;if(obstacleMeshes.some(o=>x>o.x-o.w/2&&x<o.x+o.w/2&&z>o.z-o.d/2&&z<o.z+o.d/2))return false;}return true;}
  function botShoot(b){
    addTracer(V3(b.x,1.18,b.z),V3(player.x,.9,player.z),0xf39b70,.14);
    if(Math.random()<.58){player.hp-=rand(8,15);damageTimer=.32;ui.damageFlash.style.opacity='.9';updateHUD();if(player.hp<=0){player.hp=0;scoreEnemy++;feed(b.name,'YOU',true);endRound(false);}}
  }
  function endRound(won){if(state!=='playing')return;state='roundend';if(won){scorePlayer++;credits+=300;}else scoreEnemy++;ui.roundTitle.textContent=scorePlayer>=3?'MISSION COMPLETE':scoreEnemy>=3?'MISSION FAILED':won?'ROUND WON':'ROUND LOST';ui.roundCopy.textContent=won?'Sector secured. Contract bonus awarded.':'The opposition held the line. Regroup and go again.';ui.resultPlayer.textContent=scorePlayer;ui.resultEnemy.textContent=scoreEnemy;ui.continueButton.querySelector('span').textContent=scorePlayer>=3||scoreEnemy>=3?'RETURN TO ARMORY':'DEPLOY AGAIN';ui.roundScreen.classList.remove('hidden');updateHUD();document.exitPointerLock?.();}
  function frame(){const dt=Math.min(.04,clock3.getDelta());elapsed+=dt;if(state==='playing')update(dt);animate(dt);renderer.render(scene,camera);}
  function update(dt){
    roundTime-=dt;fireTimer=Math.max(0,fireTimer-dt);if(reloadTimer>0)completeReload(dt);playerMove(dt);
    if(fireHeld)shoot();for(const b of bots)botUpdate(b,dt);
    const nearest=props.some(p=>!p.opened&&Math.hypot(player.x-p.x,player.z-p.z)<2.3);ui.interaction.classList.toggle('hidden',!nearest);
    if(roundTime<=0){endRound(bots.filter(b=>b.alive).length<3);}
    if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show');}if(hitTimer>0){hitTimer-=dt;if(hitTimer<=0)ui.hitMarker.classList.add('hidden');}if(damageTimer>0){damageTimer-=dt;if(damageTimer<=0)ui.damageFlash.style.opacity='0';}updateHUD();
  }
  function animate(dt){
    if(state==='menu'){camera.position.set(Math.sin(elapsed*.12)*.18,2.05,12.4);camera.rotation.set(-.07,Math.sin(elapsed*.12)*-.14,0,'YXZ');}
    for(const t of tracers){t.life-=dt;t.line.material.opacity=Math.max(0,t.life/.14);}for(let i=tracers.length-1;i>=0;i--)if(tracers[i].life<=0){scene.remove(tracers[i].line);tracers[i].line.geometry.dispose();tracers[i].line.material.dispose();tracers.splice(i,1);}
    if(weaponRig&&player){weaponRig.position.y=-.29+Math.sin(elapsed*8)*.006;}
  }
  function resize(){if(!renderer||!camera)return;renderer.setSize(innerWidth,innerHeight,false);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}
  init();
})();

