import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--use-gl=swiftshader'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://127.0.0.1:8000', { waitUntil: 'networkidle' });
await page.locator('#startButton').click();
await page.waitForTimeout(1400);
const playing = await page.locator('#hud').isVisible();
await page.locator('#pauseButton').click();
const paused = await page.locator('#pauseScreen').isVisible();
await page.locator('#resumeButton').click();
const resumed = !(await page.locator('#pauseScreen').isVisible());
await page.keyboard.press('2');
const weapon = await page.locator('#weaponName').textContent();
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/iron-sight-latest.jpg', type: 'jpeg', quality: 78 });
console.log(JSON.stringify({ playing, paused, resumed, weapon, errors }, null, 2));
await browser.close();
EOF

